    final modelId = preset.mediaSlots[slot];
    await store.setOverride(
      slot,
      modelId == null
          ? null
          : MediaSlotOverride(
              providerKind: 'openai-completions',
              baseUrl: baseUrl,
              modelId: modelId,
              apiKeyName: keyName,
            ),
